import * as T from 'three';
import {OrbitControls} from './vendor/OrbitControls.js';
import {GLTFLoader} from './vendor/loaders/GLTFLoader.js';
import {RanchRenderer} from './ranch-renderer.js';
import {ranchMaterial} from './tile-materials.js';
import {calibratedScale,modelDimensions,calibrationStatus} from './model-calibration.js';
import {clipHex,inHex} from './garden-farm.js';
import {composeWoodland,woodlandTerrain as gardenTerrain,WOODLAND_ASSETS as GARDEN_ASSETS,DEFAULT_WOODLAND,WOODLAND_PRESETS} from './working-woodland.js';
const $=id=>document.getElementById(id),host=$('scene-viewport'),scene=new T.Scene();scene.background=new T.Color('#e4e9d8');
const renderer=new RanchRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.shadowMap.autoUpdate=false;host.append(renderer.domElement);
const camera=new T.PerspectiveCamera(37,1,.1,1000),orbit=new OrbitControls(camera,renderer.domElement);orbit.mouseButtons={LEFT:null,MIDDLE:T.MOUSE.ROTATE,RIGHT:T.MOUSE.PAN};orbit.enableDamping=false;orbit.maxPolarAngle=Math.PI*.46;orbit.minDistance=15;orbit.maxDistance=450;
scene.add(new T.HemisphereLight('#fff6df','#728779',1.15));const sun=new T.DirectionalLight('#fff0d2',2);sun.position.set(-60,100,40);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-65,right:65,top:65,bottom:-65,near:1,far:250});sun.shadow.normalBias=.06;scene.add(sun);
const labels=document.createElement('div');labels.className='garden-labels';host.append(labels);let world=null,terrain=null,result=null,busy=false,labelEntries=[],routeMeshes=[],request=0;
let focusWork=false;
const templates=new Map(),dimensions={},catalog=await fetch('/simulation-assets/catalog.json').then(r=>{if(!r.ok)throw Error('Asset catalog unavailable');return r.json()});
function material(color,role='ground'){return ranchMaterial(color,role);}
function mesh(geo,color,role='ground'){const m=new T.Mesh(geo,material(color,role));m.receiveShadow=true;return m;}
function box(g,x,y,z,w,h,d,color,role='timber'){const m=mesh(new T.BoxGeometry(w,h,d),color,role);m.position.set(x,y,z);m.castShadow=true;g.add(m);return m;}
async function load(id){if(!templates.has(id))templates.set(id,(async()=>{
 if(id.startsWith('WW-')){const g=(await new GLTFLoader().loadAsync('/woodland-assets/'+id+'.glb')).scene;g.traverse(o=>{if(o.isMesh){o.castShadow=o.receiveShadow=true;o.userData.template=true;}});return g;}
 const record=catalog.find(a=>a.id===id);if(!record)throw Error('Missing asset '+id);const parts=await fetch(record.json).then(r=>{if(!r.ok)throw Error('Could not load '+id);return r.json()}),group=new T.Group();for(const p of parts){const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(p.positions,3));if(p.normals?.length===p.positions.length)geo.setAttribute('normal',new T.Float32BufferAttribute(p.normals,3));else geo.computeVertexNormals();const m=mesh(geo,new T.Color().setRGB(...p.color,T.SRGBColorSpace),p.role||'plain');m.castShadow=true;m.userData.template=true;group.add(m);}return group;})());return templates.get(id);}
async function refreshDimensions(){for(const id of GARDEN_ASSETS){const source=await load(id),size=new T.Box3().setFromObject(source).getSize(new T.Vector3());dimensions[id]=modelDimensions(id,size);}}
function addAsset(group,id,x,y,z){const source=templates.get(id);return Promise.resolve(source).then(source=>{const asset=source.clone(true),b=new T.Box3().setFromObject(asset),c=b.getCenter(new T.Vector3()),factor=calibratedScale(id)??1;asset.position.set(-c.x,-b.min.y,-c.z);const wrapper=new T.Group();wrapper.add(asset);wrapper.scale.setScalar(factor);wrapper.position.set(x,y,z);wrapper.userData={asset:id,purpose:'Declared by parent placement'};group.add(wrapper);return wrapper;});}
function release(group){if(!group)return;group.traverse(o=>{if(o.isInstancedMesh)o.dispose();if(!o.userData.template)o.geometry?.dispose();if(!o.userData.template&&o.material&&!o.material.userData.shared)o.material.dispose();});}
function render(){renderer.render(scene,camera);for(const l of labelEntries){const p=l.point.clone().project(camera);l.element.hidden=!$('woodland-labels').checked||p.z<0||p.z>1||Math.abs(p.x)>1||Math.abs(p.y)>1;l.element.style.left=(p.x+1)*host.clientWidth/2+'px';l.element.style.top=(1-p.y)*host.clientHeight/2+'px';}}
orbit.addEventListener('change',()=>{render();window.RanchView?.changed();});
function fit(top=false){const extent=focusWork?28:($('woodland-carved').checked?54:66),half=Math.min(camera.fov*Math.PI/360,Math.atan(Math.tan(camera.fov*Math.PI/360)*camera.aspect)),distance=extent/Math.sin(half);orbit.target.set(0,0,focusWork?8:0);camera.position.copy(new T.Vector3(top?.001:.75,top?1:1.12,top?.001:1.1).normalize().multiplyScalar(distance)).add(orbit.target);orbit.update();render();}
new ResizeObserver(()=>{renderer.setSize(host.clientWidth,host.clientHeight,false);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();fit();}).observe(host);
function terrainMesh(t,carved){const positions=[],water=[],colors=[],groundColors=['#aebc88','#b9c591','#9daf7e'];
 for(let x=-60;x<60;x+=2.5)for(let z=-60;z<60;z+=2.5){let poly=[{x,z},{x:x+2.5,z},{x:x+2.5,z:z+2.5},{x,z:z+2.5}];if(carved)poly=clipHex(poly);if(poly.length<3)continue;const s=t.sample(x+1.25,z+1.25),color=new T.Color(s.bank<2?'#b3ae89':'#aebd89');for(let i=1;i<poly.length-1;i++)for(const p of [poly[0],poly[i+1],poly[i]]){positions.push(p.x,t.height(p.x,p.z),p.z);colors.push(color.r,color.g,color.b);}
  if(s.bank<0){const brook=t.world.water.brook.centerline,idx=Math.max(0,Math.min(brook.length-1,Math.round((x+90)/180*(brook.length-1)))),h=brook[idx][2]-t.datum;for(let i=1;i<poly.length-1;i++)for(const p of [poly[0],poly[i],poly[i+1]])water.push(p.x,h+.03,p.z);}
 }
 const g=new T.Group(),geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));geo.setAttribute('color',new T.Float32BufferAttribute(colors,3));geo.computeVertexNormals();const ground=new T.Mesh(geo,new T.MeshLambertMaterial({vertexColors:true}));ground.receiveShadow=true;g.add(ground);
 if(water.length){const waterGeo=new T.BufferGeometry();waterGeo.setAttribute('position',new T.Float32BufferAttribute(water,3));waterGeo.computeVertexNormals();const m=mesh(waterGeo,'#87b5af');m.material.side=T.DoubleSide;g.add(m);}
 // The cut exposes a continuous earth edge without clipping buildings or routes.
 const boundary=carved?Array.from({length:6},(_,i)=>({x:50*Math.sin(i*Math.PI/3),z:50*Math.cos(i*Math.PI/3)})):[{x:-60,z:-60},{x:-60,z:60},{x:60,z:60},{x:60,z:-60}],side=[];
 for(let i=0;i<boundary.length;i++){const a=boundary[i],b=boundary[(i+1)%boundary.length],n=40;for(let j=0;j<n;j++){const p={x:a.x+(b.x-a.x)*j/n,z:a.z+(b.z-a.z)*j/n},q={x:a.x+(b.x-a.x)*(j+1)/n,z:a.z+(b.z-a.z)*(j+1)/n};for(const v of [[p.x,t.height(p.x,p.z),p.z],[q.x,t.height(q.x,q.z),q.z],[p.x,-5,p.z],[q.x,t.height(q.x,q.z),q.z],[q.x,-5,q.z],[p.x,-5,p.z]])side.push(...v);}}
 const sideGeo=new T.BufferGeometry();sideGeo.setAttribute('position',new T.Float32BufferAttribute(side,3));sideGeo.computeVertexNormals();const wall=mesh(sideGeo,'#958467');wall.material.side=T.DoubleSide;g.add(wall);return g;
}
function routeGeometry(path,t){const points=path.points.filter((p,i,a)=>!i||i===a.length-1||Math.abs((p.x-a[i-1].x)*(a[i+1].z-p.z)-(p.z-a[i-1].z)*(a[i+1].x-p.x))>1e-7),positions=[],edges=[];
 for(let i=0;i<points.length;i++){const p=points[i],a=points[Math.max(0,i-1)],b=points[Math.min(points.length-1,i+1)],prev=new T.Vector2(p.x-a.x,p.z-a.z),next=new T.Vector2(b.x-p.x,b.z-p.z);if(!prev.length())prev.copy(next);if(!next.length())next.copy(prev);prev.normalize();next.normalize();const n1=new T.Vector2(-prev.y,prev.x),n2=new T.Vector2(-next.y,next.x),m=n1.clone().add(n2).normalize(),scale=Math.min(path.width,path.width/2/Math.max(.5,m.dot(n2)));edges.push([{x:p.x+m.x*scale,z:p.z+m.y*scale},{x:p.x-m.x*scale,z:p.z-m.y*scale}]);}
 // Subdivide long runs so roads follow the sampled ground instead of cutting through a hill.
 for(let i=1;i<edges.length;i++){const a=edges[i-1],b=edges[i],steps=Math.max(1,Math.ceil(Math.hypot(points[i].x-points[i-1].x,points[i].z-points[i-1].z)));for(let j=0;j<steps;j++){const f=j/steps,g=(j+1)/steps,corner=[{x:a[0].x+(b[0].x-a[0].x)*f,z:a[0].z+(b[0].z-a[0].z)*f},{x:a[1].x+(b[1].x-a[1].x)*f,z:a[1].z+(b[1].z-a[1].z)*f},{x:a[0].x+(b[0].x-a[0].x)*g,z:a[0].z+(b[0].z-a[0].z)*g},{x:a[1].x+(b[1].x-a[1].x)*g,z:a[1].z+(b[1].z-a[1].z)*g}];for(const k of [0,1,2,2,1,3]){const p=corner[k];positions.push(p.x,t.height(p.x,p.z)+.07+(path.traffic==='cart'?.002:0),p.z);}}}
 const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));geo.computeVertexNormals();return geo;
}
async function draw(next){const t=gardenTerrain(next.recipe),group=new T.Group();group.add(terrainMesh(t,$('woodland-carved').checked));const newRoutes=[];
 for(const route of next.routes){const baseColor=route.traffic==='cart'?'#c6b28a':'#dfcf9f',m=new T.Mesh(routeGeometry(route,t),new T.MeshBasicMaterial({color:baseColor,side:T.DoubleSide,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-2,polygonOffsetUnits:-4}));m.renderOrder=2;m.userData.route=route.id;group.add(m);newRoutes.push({mesh:m,route,baseColor});}
 for(const o of next.items){if(o.foundationDepth>.03)box(group,o.x,o.y-o.foundationDepth/2,o.z,o.w,o.foundationDepth,o.d,'#aa9677','ground');if(o.model){const a=await addAsset(group,o.model,o.x,o.y+.02,o.z);a.rotation.y=o.orientation||0;a.userData={...a.userData,id:o.id,purpose:o.purpose,simulation:o.simulation};}}

 // Batch standing woodland so dense forest remains practical while orbiting on a phone.
 const tree=await templates.get('tree-standing');tree.updateMatrixWorld(true);const bounds=new T.Box3().setFromObject(tree),center=bounds.getCenter(new T.Vector3()),grounded=new T.Matrix4().makeTranslation(-center.x,-bounds.min.y,-center.z),factor=calibratedScale('tree-standing')??1;
 tree.traverse(source=>{if(!source.isMesh)return;const batch=new T.InstancedMesh(source.geometry,source.material,next.forest.length);batch.castShadow=batch.receiveShadow=true;batch.userData={template:true,purpose:'Managed woodland reserve',instances:next.forest};next.forest.forEach((o,i)=>{const placement=new T.Matrix4().compose(new T.Vector3(o.x,o.y,o.z),new T.Quaternion().setFromAxisAngle(new T.Vector3(0,1,0),o.orientation||0),new T.Vector3(factor,factor,factor));batch.setMatrixAt(i,placement.multiply(grounded).multiply(source.matrixWorld));});batch.computeBoundingSphere();group.add(batch);});
 const work=next.items.find(o=>o.id==='processing');const worker=await addAsset(group,'WW-006',work.interaction.x+1.5,t.height(work.interaction.x+1.5,work.interaction.z),work.interaction.z);worker.userData.purpose='Static illustration of a woodland handworker; labor is planned';
 for(const reservation of next.reservations){const points=[];for(let i=0;i<=64;i++){const x=reservation.x+Math.cos(i/64*Math.PI*2)*reservation.radius,z=reservation.z+Math.sin(i/64*Math.PI*2)*reservation.radius;points.push(new T.Vector3(x,t.height(x,z)+.08,z));}const line=new T.Line(new T.BufferGeometry().setFromPoints(points),new T.LineBasicMaterial({color:'#ae9770',transparent:true,opacity:.6}));group.add(line);}
 if(world){scene.remove(world);release(world);}world=group;terrain=t;routeMeshes=newRoutes;scene.add(world);renderer.shadowMap.needsUpdate=true;
 labels.replaceChildren();labelEntries=[];for(const o of next.items){const el=document.createElement('span');el.className='garden-label';el.textContent=o.id.replaceAll('-',' ');labels.append(el);labelEntries.push({id:o.id,element:el,point:new T.Vector3(o.x,o.y+o.h+1,o.z)});}
 result=next;updateInfo();render();window.RanchView?.changed();
}

let recipe={...DEFAULT_WOODLAND};
function updateInfo(){if(!result)return;$('woodland-sentence').textContent=result.grammar.sentence;$('woodland-caption').textContent=WOODLAND_PRESETS[result.recipe.preset].output;$('woodland-inspect').replaceChildren(...result.items.map(o=>new Option(o.id.replaceAll('-',' '),o.id)));inspect();}
function inspect(){if(!result)return;const o=result.items.find(o=>o.id===$('woodland-inspect').value);$('woodland-purpose').textContent=`${o.purpose}. ${o.w.toFixed(1)} x ${o.d.toFixed(1)} m. Intended work: ${o.activities.join(', ')}. Behavior planned.`;labelEntries.forEach(l=>l.element.classList.toggle('active',l.id===o.id));render();window.RanchView?.changed();}
function controls(){for(const el of document.querySelectorAll('[data-setting]'))el.setAttribute('aria-pressed',String(recipe[el.dataset.setting]===el.dataset.value));$('woodland-seed').textContent='Variation '+recipe.seed;}
async function build(next=recipe){if(busy)return;busy=true;$('woodland-status').textContent='Arranging work and checking access...';document.querySelectorAll('[data-setting],#woodland-vary,#woodland-carved,#woodland-export').forEach(e=>e.disabled=true);window.RanchView?.changed();await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));try{await refreshDimensions();const composed=composeWoodland(next,dimensions);await draw(composed);recipe={...composed.recipe};controls();$('woodland-status').textContent='Connected and ready to explore.';}catch(e){$('woodland-status').textContent=e.message+(result?' Previous woodland retained.':'');}finally{busy=false;document.querySelectorAll('[data-setting],#woodland-vary,#woodland-carved,#woodland-export').forEach(e=>e.disabled=false);window.RanchView?.changed();}}
for(const el of document.querySelectorAll('[data-setting]'))el.onclick=()=>build({...recipe,[el.dataset.setting]:el.dataset.value});
$('woodland-vary').onclick=()=>build({...recipe,seed:crypto.getRandomValues(new Uint32Array(1))[0]||1});
$('woodland-fit').onclick=()=>{focusWork=false;fit()};$('woodland-work').onclick=()=>{focusWork=true;fit()};$('woodland-top').onclick=()=>fit(true);
$('woodland-labels').onchange=()=>{render();window.RanchView?.changed()};$('woodland-carved').onchange=async()=>{if(result){recipe={...recipe,carved:$('woodland-carved').checked};await draw({...result,recipe});fit();}};
$('woodland-inspect').onchange=inspect;
for(const el of document.querySelectorAll('[data-panel]'))el.onclick=()=>{$('woodland-compose').hidden=el.dataset.panel!=='compose';$('woodland-details').hidden=el.dataset.panel!=='details';window.RanchView?.changed();};
$('woodland-export').onclick=()=>{if(!result)return;const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='working-woodland-'+recipe.seed+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
window.RanchView?.register('workingWoodland',()=>({busy,recipe:result?.recipe,sentence:result?.grammar.sentence,validation:result?.validation,items:result?.items,forestCount:result?.forest.length,routes:result?.routes,interfaces:result?.interfaces,calibration:calibrationStatus,camera:camera.position.toArray()}),render);
window.addEventListener('ranch-model-calibration',()=>{if(result&&!busy)build(recipe)});
controls();await build();fit();if(innerWidth<800)window.RanchDrawers?.close();
